        "content": "資料JSON:\n{\"holder\":\"A\",\"experiences\":[{\"episode_id\":\"E09F5589ACB\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":17,\"paper_success\":6},{\"episode_id\":\"ED37E0BA952\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":12,\"paper_success\":4},{\"episode_id\":\"E1E372E5608\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":12,\"paper_success\":13},{\"episode_id\":\"E43A30FE520\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":8,\"paper_success\":8},{\"episode_id\":\"EF4E307EAA1\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":3,\"attempts_per_medium\":40,\"digital_success\":19,\"paper_success\":36}],\"own_judgment\":{\"record_id\":\"Q9016B98EA0\",\"author\":\"A\",\"body\":{\"choice\":\"PAPER\",\"evidence_refs\":[\"E1E372E5608\",\"E43A30FE520\"],\"subject\":\"A\"}},\"initial_proposal\":{\"record_id\":\"Q3945A865E1\",\"author\":\"B\",\"body\":{\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"evidence_refs\":[\"E09F5589ACB\",\"ED37E0BA952\",\"E1E372E5608\",\"E43A30FE520\",\"EF4E307EAA1\"]}},\"joint_candidate_totals\":[{\"candidate_id\":\"Y\",\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"projected_total_success_per_40_each\":45},{\"candidate_id\":\"X\",\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"projected_total_success_per_40_each\":43}],\"own_experience_summary\":{\"observer\":\"A\",\"experience_refs\":[\"E1E372E5608\",\"E43A30FE520\"],\"attempts_per_medium_total\":40,\"projected_success_per_40\":{\"DIGITAL\":20,\"PAPER\":21}}}",
