        "content": "資料JSON:\n{\"holder\":\"B\",\"experiences\":[{\"episode_id\":\"EAFB0B4F888\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":1,\"attempts_per_medium\":20,\"paper_success\":11,\"digital_success\":14},{\"episode_id\":\"E3BC0135CC3\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":2,\"attempts_per_medium\":20,\"paper_success\":17,\"digital_success\":11},{\"episode_id\":\"E4CD06F7540\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":1,\"attempts_per_medium\":20,\"paper_success\":11,\"digital_success\":13},{\"episode_id\":\"EF9D6953FF7\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":2,\"attempts_per_medium\":20,\"paper_success\":7,\"digital_success\":7},{\"episode_id\":\"E96601808DF\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":3,\"attempts_per_medium\":40,\"paper_success\":6,\"digital_success\":29}],\"own_judgment\":{\"record_id\":\"Q6DF586CEBE\",\"author\":\"B\",\"body\":{\"choice\":\"PAPER\",\"evidence_refs\":[\"E4CD06F7540\",\"EF9D6953FF7\"],\"subject\":\"B\"}},\"initial_proposal\":{\"record_id\":\"Q4A67A15B6A\",\"author\":\"A\",\"body\":{\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"evidence_refs\":[\"EAFB0B4F888\",\"E3BC0135CC3\",\"E4CD06F7540\",\"EF9D6953FF7\",\"E96601808DF\"]}},\"joint_candidate_totals\":[{\"candidate_id\":\"X\",\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"projected_total_success_per_40_each\":45},{\"candidate_id\":\"Y\",\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"projected_total_success_per_40_each\":37}]}",
