        "content": "資料JSON:\n{\"holder\":\"A\",\"experiences\":[{\"episode_id\":\"E90A8ED1830\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":9,\"paper_success\":18},{\"episode_id\":\"EEDE6BF0309\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":4,\"paper_success\":18},{\"episode_id\":\"E10033DC2AD\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":15,\"paper_success\":18},{\"episode_id\":\"E88EA709869\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":9,\"paper_success\":16},{\"episode_id\":\"E70C8572D8B\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":3,\"attempts_per_medium\":40,\"digital_success\":23,\"paper_success\":4}],\"own_judgment\":{\"record_id\":\"QAE905C971B\",\"author\":\"A\",\"body\":{\"choice\":\"PAPER\",\"evidence_refs\":[\"E10033DC2AD\",\"E88EA709869\"],\"subject\":\"A\"}},\"initial_proposal\":{\"record_id\":\"Q9635AB88D7\",\"author\":\"B\",\"body\":{\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"evidence_refs\":[\"E90A8ED1830\",\"EEDE6BF0309\",\"E10033DC2AD\",\"E88EA709869\",\"E70C8572D8B\"]}},\"joint_candidate_totals\":[{\"candidate_id\":\"X\",\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"projected_total_success_per_40_each\":52},{\"candidate_id\":\"Y\",\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"projected_total_success_per_40_each\":44}],\"own_experience_summary\":{\"observer\":\"A\",\"experience_refs\":[\"E10033DC2AD\",\"E88EA709869\"],\"attempts_per_medium_total\":40,\"projected_success_per_40\":{\"DIGITAL\":24,\"PAPER\":34}}}",
