        "content": "資料JSON:\n{\"holder\":\"A\",\"experiences\":[{\"episode_id\":\"E8D4D3EC726\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":18,\"paper_success\":12},{\"episode_id\":\"E00BB4AF025\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":18,\"paper_success\":8},{\"episode_id\":\"EEB9C548F89\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":18,\"paper_success\":14},{\"episode_id\":\"E665265C6B1\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":6,\"paper_success\":7},{\"episode_id\":\"E4913713816\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":3,\"attempts_per_medium\":40,\"digital_success\":18,\"paper_success\":24}],\"own_judgment\":{\"record_id\":\"Q2AEAADF263\",\"author\":\"A\",\"body\":{\"choice\":\"DIGITAL\",\"evidence_refs\":[\"EEB9C548F89\",\"E665265C6B1\"],\"subject\":\"A\"}},\"initial_proposal\":{\"record_id\":\"QC556AE59DD\",\"author\":\"B\",\"body\":{\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"evidence_refs\":[\"E8D4D3EC726\",\"E00BB4AF025\",\"EEB9C548F89\",\"E665265C6B1\",\"E4913713816\"]}},\"joint_candidate_totals\":[{\"candidate_id\":\"X\",\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"projected_total_success_per_40_each\":46},{\"candidate_id\":\"Y\",\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"projected_total_success_per_40_each\":48}]}",
