        "content": "資料JSON:\n{\"holder\":\"B\",\"experiences\":[{\"episode_id\":\"E2EC15A02F2\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":1,\"attempts_per_medium\":20,\"paper_success\":8,\"digital_success\":12},{\"episode_id\":\"E3A957638CC\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":2,\"attempts_per_medium\":20,\"paper_success\":6,\"digital_success\":18},{\"episode_id\":\"E09F561D7FC\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":1,\"attempts_per_medium\":20,\"paper_success\":7,\"digital_success\":7},{\"episode_id\":\"EF69B4DCB2B\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":2,\"attempts_per_medium\":20,\"paper_success\":7,\"digital_success\":8},{\"episode_id\":\"E04486A912D\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":3,\"attempts_per_medium\":40,\"paper_success\":26,\"digital_success\":8}],\"own_judgment\":{\"record_id\":\"Q6EB2A0941C\",\"author\":\"B\",\"body\":{\"choice\":\"UNDECIDED\",\"evidence_refs\":[\"E09F561D7FC\",\"EF69B4DCB2B\"],\"subject\":\"B\"}},\"initial_proposal\":{\"record_id\":\"Q08D6040F05\",\"author\":\"A\",\"body\":{\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"DIGITAL\"},\"evidence_refs\":[\"E2EC15A02F2\",\"E3A957638CC\",\"E09F561D7FC\",\"EF69B4DCB2B\",\"E04486A912D\"]}},\"joint_candidate_totals\":[{\"candidate_id\":\"Y\",\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"projected_total_success_per_40_each\":33},{\"candidate_id\":\"X\",\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"projected_total_success_per_40_each\":35}]}",
