        "content": "資料JSON:\n{\"holder\":\"B\",\"experiences\":[{\"episode_id\":\"EC5E18C2CFD\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":1,\"attempts_per_medium\":20,\"paper_success\":9,\"digital_success\":5},{\"episode_id\":\"EF5ABF4D839\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":2,\"attempts_per_medium\":20,\"paper_success\":4,\"digital_success\":9},{\"episode_id\":\"E9D24EAF071\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":1,\"attempts_per_medium\":20,\"paper_success\":17,\"digital_success\":14},{\"episode_id\":\"E58341A6142\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":2,\"attempts_per_medium\":20,\"paper_success\":6,\"digital_success\":4},{\"episode_id\":\"E4C2344368D\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":3,\"attempts_per_medium\":40,\"paper_success\":33,\"digital_success\":26}],\"own_judgment\":{\"record_id\":\"Q23DB5804EB\",\"author\":\"B\",\"body\":{\"choice\":\"PAPER\",\"evidence_refs\":[\"E9D24EAF071\",\"E58341A6142\"],\"subject\":\"B\"}},\"initial_proposal\":{\"record_id\":\"Q950C0CA176\",\"author\":\"A\",\"body\":{\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"evidence_refs\":[\"EC5E18C2CFD\",\"EF5ABF4D839\",\"E9D24EAF071\",\"E58341A6142\",\"E4C2344368D\"]}},\"joint_candidate_totals\":[{\"candidate_id\":\"X\",\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"projected_total_success_per_40_each\":41},{\"candidate_id\":\"Y\",\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"projected_total_success_per_40_each\":43}],\"own_experience_summary\":{\"observer\":\"B\",\"experience_refs\":[\"E9D24EAF071\",\"E58341A6142\"],\"attempts_per_medium_total\":40,\"projected_success_per_40\":{\"PAPER\":23,\"DIGITAL\":18}}}",
