        "content": "資料JSON:\n{\"holder\":\"A\",\"experiences\":[{\"episode_id\":\"E7913387DC2\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":12,\"paper_success\":14},{\"episode_id\":\"E362D409049\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":10,\"paper_success\":16},{\"episode_id\":\"E351CBB35FC\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":1,\"attempts_per_medium\":20,\"digital_success\":17,\"paper_success\":13},{\"episode_id\":\"EAA87417B99\",\"observer\":\"A\",\"site\":\"区画1\",\"session\":2,\"attempts_per_medium\":20,\"digital_success\":8,\"paper_success\":7},{\"episode_id\":\"EA11ADCC071\",\"observer\":\"B\",\"site\":\"区画2\",\"session\":3,\"attempts_per_medium\":40,\"digital_success\":24,\"paper_success\":22}],\"own_judgment\":{\"record_id\":\"QDEA60100C3\",\"author\":\"A\",\"body\":{\"choice\":\"DIGITAL\",\"evidence_refs\":[\"E351CBB35FC\",\"EAA87417B99\"],\"subject\":\"A\"}},\"initial_proposal\":{\"record_id\":\"Q7A1F084817\",\"author\":\"B\",\"body\":{\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"DIGITAL\"},\"evidence_refs\":[\"E7913387DC2\",\"E362D409049\",\"E351CBB35FC\",\"EAA87417B99\",\"EA11ADCC071\"]}},\"joint_candidate_totals\":[{\"candidate_id\":\"Y\",\"allocation\":{\"A\":\"DIGITAL\",\"B\":\"PAPER\"},\"projected_total_success_per_40_each\":51},{\"candidate_id\":\"X\",\"allocation\":{\"A\":\"PAPER\",\"B\":\"DIGITAL\"},\"projected_total_success_per_40_each\":43}]}",
